	DIS(fprintf (logfile, "move.%c $p%u, [$r%u%s\n",

		     memsize_char(memsize), 

		     dc->op2, dc->op1, dc->postinc ? "+]" : "]"));



	/* prepare store. Address in T0, value in T1.  */

	if (dc->op2 == PR_CCS)

