	gen_store(dc, cpu_R[dc->op1], t0, memsize);

	tcg_temp_free(t0);



	cris_cc_mask(dc, 0);

	if (dc->postinc)

		tcg_gen_addi_tl(cpu_R[dc->op1], cpu_R[dc->op1], memsize);

	return 2;

}

